def expand_dims(
    self,
    dim: Union[None, Hashable, Sequence[Hashable], Mapping[Any, Any]] = None,
    axis: Union[None, int, Sequence[int]] = None,
    **dim_kwargs: Any,
) -> "Dataset":
    """Return a new object with an additional axis (or axes) inserted at
    the corresponding position in the array shape.  The new object is a
    view into the underlying array, not a copy.
    If dim is already a scalar coordinate, it will be promoted to a 1D
    coordinate consisting of a single value.
    Parameters
    ----------
    dim : hashable, sequence of hashable, mapping, or None
        Dimensions to include on the new variable. If provided as hashable
        or sequence of hashable, then dimensions are inserted with length
        1. If provided as a mapping, then the keys are the new dimensions
        and the values are either integers (giving the length of the new
        dimensions) or array-like (giving the coordinates of the new
        dimensions).
    axis : int, sequence of int, or None
        Axis position(s) where new axis is to be inserted (position(s) on
        the result array). If a list (or tuple) of integers is passed,
        multiple axes are inserted. In this case, dim arguments should be
        same length list. If axis=None is passed, all the axes will be
        inserted to the start of the result array.
    **dim_kwargs : int or sequence or ndarray
        The keywords are arbitrary dimensions being inserted and the values
        are either the lengths of the new dims (if int is given), or their
        coordinates. Note, this is an alternative to passing a dict to the
        dim kwarg and will only be used if dim is None.
    Returns
    -------
    expanded : same type as caller
        This object, but with an additional dimension(s).
    """
    if dim is None:
        pass
    elif isinstance(dim, Mapping):
        # We're later going to modify dim in place; don't tamper with
        # the input
        dim = dict(dim)
    elif isinstance(dim, int):
        raise TypeError(
            "dim should be hashable or sequence of hashables or mapping"
        )
    elif isinstance(dim, str) or not isinstance(dim, Sequence):
        dim = {dim: 1}
    elif isinstance(dim, Sequence):
        if len(dim) != len(set(dim)):
            raise ValueError("dims should not contain duplicate values.")
        dim = {d: 1 for d in dim}
    dim = either_dict_or_kwargs(dim, dim_kwargs, "expand_dims")
    assert isinstance(dim, MutableMapping)
    if axis is None:
        axis = list(range(len(dim)))
    elif not isinstance(axis, Sequence):
        axis = [axis]
    if len(dim) != len(axis):
        raise ValueError("lengths of dim and axis should be identical.")
    for d in dim:
        if d in self.dims:
            raise ValueError(f"Dimension {d} already exists.")
        if d in self._variables and not utils.is_scalar(self._variables[d]):
            raise ValueError(
                "{dim} already exists as coordinate or"
                " variable name.".format(dim=d)
            )
    variables: Dict[Hashable, Variable] = {}
    coord_names = self._coord_names.copy()
    # If dim is a dict, then ensure that the values are either integers
    # or iterables.
    for k, v in dim.items():
        if hasattr(v, "__iter__"):
            # If the value for the new dimension is an iterable, then
            # save the coordinates to the variables dict, and set the
            # value within the dim dict to the length of the iterable
            # for later use.
            variables[k] = xr.IndexVariable((k,), v)
            coord_names.add(k)
            dim[k] = variables[k].size
        elif isinstance(v, int):
            pass  # Do nothing if the dimensions value is just an int
        else:
            raise TypeError(
                "The value of new dimension {k} must be "
                "an iterable or an int".format(k=k)
            )
    for k, v in self._variables.items():
        if k not in dim:
            if k in coord_names:  # Do not change coordinates
                variables[k] = v
            else:
                result_ndim = len(v.dims) + len(axis)
                for a in axis:
                    if a < -result_ndim or result_ndim - 1 < a:
                        raise IndexError(
                            f"Axis {a} of variable {k} is out of bounds of the "
                            f"expanded dimension size {result_ndim}"
                        )
                axis_pos = [a if a >= 0 else result_ndim + a for a in axis]
                if len(axis_pos) != len(set(axis_pos)):
                    raise ValueError("axis should not contain duplicate values")
                # We need to sort them to make sure `axis` equals to the
                # axis positions of the result array.
                zip_axis_dim = sorted(zip(axis_pos, dim.items()))
                all_dims = list(zip(v.dims, v.shape))
                for d, c in zip_axis_dim:
                    all_dims.insert(d, c)
                variables[k] = v.set_dims(dict(all_dims))
        else:
            # If dims includes a label of a non-dimension coordinate,
            # it will be promoted to a 1D coordinate with a single value.
            variables[k] = v.set_dims(k).to_index_variable()
    new_dims = self._dims.copy()
    new_dims.update(dim)
    return self._replace_vars_and_dims(
        variables, dims=new_dims, coord_names=coord_names
    )
